SELECT gc.common_id, gc.common_name, gc.common_promotion_tips, gc.cat_id, gc.cat_name, gc.shop_id, gc.shop_name, gc.brand_id, gc.brand_name, gc.common_image, gc.common_state, gc.common_verify, gc.common_add_time, gc.common_sell_time, gc.common_price, gc.common_market_price, gc.common_cost_price, gc.common_alarm, gc.goods_type, gc.common_update_time, gc.common_is_locked, gc.type, gc.common_is_screen, sc.tax_id as business_id, sc.business_licence_pic as businessLicenseElectronic, sb.shop_business, gc.common_verify_time, gc.order_operator, gc.order_operator_time, gc.virtual_goods ,sb.shop_type,sb.shop_self_support FROM ${database.prefix.goods}hou_goods_common gc LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON sb.supplier_shop_id = gc.shop_id LEFT JOIN ${database.prefix.supplier}hou_supplier_shop_join_base sc ON sc.user_id = sb.user_id left join ${database.prefix.base}hou_base_dealer_putaway_record dr on gc.common_id = dr.dealer_common_id WHERE common_state NOT IN (3, 5) and gc.integral_goods = 1 and gc.shop_status = 3 and (dr.is_price_update = 1 or dr.is_price_update is null) AND (gc.integral_goods <> 0 or gc.integral_goods is null)
and sb.shop_business in (0,1,2) and sb.shop_self_support = 'false'
and sb.shop_self_support = 'true'
and sb.shop_business = #{param.shopBusiness} and sb.shop_self_support = 'false'
and gc.shop_id = #{param.shopId}
and gc.goods_type <> 3
and sb.shop_type <> 2
and gc.virtual_goods= #{param.virtualGoods}
and gc.common_alarm <= #{param.inventoryWarning,jdbcType=INTEGER}
and gc.common_verify= #{param.commonVerify,jdbcType=INTEGER}
and gc.common_is_locked= #{param.commonIsLocked,jdbcType=INTEGER}
and gc.common_is_screen = #{param.commonIsScreen,jdbcType=INTEGER}
and gc.cat_id in ( SELECT cat_id FROM ( SELECT t1.cat_id, t1.cat_parent_id, t1.cat_level, IF ( FIND_IN_SET( cat_parent_id, @pids ) > 0, @pids := CONCAT( @pids, ',', cat_id ), 0 ) AS ischild, @l := @l + 1 AS LEVEL FROM ( SELECT cat_id, cat_level, cat_parent_id FROM ${database.prefix.goods}hou_goods_cat t ORDER BY cat_parent_id, cat_id ) t1, ( SELECT @pids := #{param.catId,jdbcType=INTEGER}, @l := 0 ) t2 ) t3 WHERE (ischild != 0 OR cat_id = #{param.catId,jdbcType=INTEGER}) and cat_level not in (1,2) )
and gc.common_state= #{param.commonState,jdbcType=INTEGER}
and gc.common_name LIKE CONCAT('%',#{param.commonName },'%')
and sb.shop_name LIKE CONCAT('%',#{param.shopName },'%')
and gc.brand_name LIKE CONCAT('%',#{param.brandName },'%')
and gc.common_id NOT IN (SELECT common_id from gdb_promotion_none_common where activity_none_type = #{param.opType})
and gc.goods_type = #{param.goodsType}
GROUP BY gc.common_id ORDER BY gc.common_update_time desc

SELECT gb.goods_id, gb.common_id, gb.goods_name, gb.goods_price, gb.goods_market_price, gb.goods_image, gb.shop_id, gb.shop_name, gb.goods_salenum FROM ${database.prefix.goods}hou_goods_base gb LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON ( gb.common_id = gc.common_id ) LEFT JOIN ${database.prefix.goods}hou_goods_stock gs on gb.goods_id = gs.goods_id WHERE gc.common_state = 1 AND gc.goods_type = #{goodsType} and gc.common_verify = 1 AND gb.goods_is_shelves = 1 AND gs.goods_stock > 0 AND gb.cat_id IN
#{catId}
ORDER BY gb.goods_salenum DESC LIMIT 8

SELECT c.common_id, c.goods_id, c.common_name, c.common_promotion_tips, c.common_image, c.common_price, c.common_market_price, c.common_salenum,c.common_is_xian,c.corner_url from ( select gb.common_id, gb.goods_id, gc.common_name, gc.common_promotion_tips, gc.common_image, gc.common_price, gc.common_market_price, gc.common_salenum,gc.common_is_xian FROM ${database.prefix.goods}hou_goods_base gb LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON gb.common_id = gc.common_id where gb.goods_is_shelves =1 and gb.goods_id in
#{goodId}
order by field( gb.goods_id,
#{goodId}
) ) c GROUP BY c.common_id

SELECT gmgb.goods_id, gmgb.common_id, gmgb.goods_name, gmgb.goods_spec, gmgb.goods_price, ggb.shop_gate_goods_stock, gs.goods_stock, gmgb.goods_shop_gate_stock AS shopGateStockMax, gmgb.goods_image, gmgb.goods_cubage, gmgb.goods_click, gmgb.goods_salenum, gmgb.goods_collect, gmgb.goods_market_price FROM ${database.prefix.goods}hou_goods_base gmgb LEFT JOIN ${database.prefix.goods}hou_goods_stock gs on gmgb.goods_id = gs.goods_id LEFT JOIN ${database.prefix.business}hou_shop_gate_goods_base ggb ON gmgb.goods_id = ggb.goods_id WHERE gmgb.is_delete != 1
and gmgb.common_id in (
#{commonId}
)

select common_id, common_name, goods_id, common_price, common_image, common_salenum, common_market_price, common_state, common_is_xian, common_promotion_tips, shop_id, points_rate from ${database.prefix.goods}hou_goods_common gc where shop_status = 3 and common_verify =1 and common_state = 1 and gc.common_is_xian = 0 and gc.integral_goods = 1
and gc.shop_id = #{param.shopId}
and gc.goods_type not in (2,3)
and cat_id in (
#{catId}
)
ORDER BY common_salenum DESC LIMIT 1000

