update ${database.prefix.goods}hou_goods_base
set goods_is_shelves = 0,is_delete = 1
where shop_id = #{shopId}

update ${database.prefix.goods}hou_goods_base
set goods_shop_gate_stock = goods_shop_gate_stock + #{param.shopGateGoodsStock,jdbcType=INTEGER}
where 1=1
  and common_id = #{param.commonId,jdbcType=INTEGER}
  and goods_id = #{param.goodsId,jdbcType=INTEGER}
  and shop_id = #{param.shopId,jdbcType=INTEGER}

UPDATE ${database.prefix.goods}hou_goods_base
set goods_salenum = CASE
                        WHEN goods_salenum > #{param.goodsNum} THEN goods_salenum - #{param.goodsNum}
                        ELSE 0 END
where goods_id = #{param.goodsId}

mapper.select:
select gb.goods_id,gb.common_id,gc.common_name,gc.common_image,gc.common_price from ${database.prefix.goods}hou_goods_base gb LEFT JOIN ${database.prefix.goods}hou_goods_common gc on gb.common_id = gc.common_id where 1 = 1
and gb.goods_id = #{param.goodsId}
and gb.common_id = #{param.commonId}
limit 1

SELECT c.common_id, c.goods_id, c.common_name, c.common_promotion_tips, c.common_image, c.common_price, c.common_market_price, c.common_salenum,c.common_is_xian from ( select gb.common_id, gb.goods_id, gc.common_name, gc.common_promotion_tips, gc.common_image, gc.common_price, gc.common_market_price, gc.common_salenum,gc.common_is_xian FROM ${database.prefix.goods}hou_goods_base gb LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON gb.common_id = gc.common_id where gb.goods_is_shelves =1 and gb.goods_id in
#{goodId}
order by field( gb.goods_id,
#{goodId}
) ) c GROUP BY c.common_id
